const fs = require('fs');

function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(text) {
  const stop = new Set(['a','as','o','os','de','da','do','das','dos','e','em','no','na','nos','nas','que','com','para','por','uma','um','ao','aos']);
  return normalize(text).split(' ').filter(t => t.length > 1 && !stop.has(t));
}

const input = $json;
input.phone = (input.phone || '').replace(/[^0-9]/g, '');
const query = input.message || '';
const tokens = tokenize(query);
const indexPath = process.env.RAG_INDEX_PATH || '/data/rag/kb-index.json';
let entries = [];

try {
  const raw = fs.readFileSync(indexPath, 'utf8');
  entries = JSON.parse(raw).entries || [];
} catch (e) {
  entries = [];
}

const scored = entries.map((entry) => {
  const content = normalize(entry.content || '');
  const section = normalize(entry.section || '');
  const keywords = (entry.keywords || []).map(normalize);
  let score = 0;
  for (const token of tokens) {
    if (keywords.some(k => k.includes(token))) score += 5;
    if (section.includes(token)) score += 3;
    if (content.includes(token)) score += 2;
  }
  if (content.includes(normalize(query))) score += 8;
  return { ...entry, score };
}).filter(e => e.score > 0).sort((a, b) => b.score - a.score);

const top = scored.slice(0, 3);
const bestScore = top[0]?.score || 0;
const ragConfident = bestScore >= 6;
const ragContext = top.map((t, i) => `[${i + 1}] ${t.source} :: ${t.section}\n${t.content}`).join('\n\n') || 'Sem trechos relevantes na KB.';

return [{
  json: {
    ...input,
    rag_matches: top,
    rag_best_score: bestScore,
    rag_confident: ragConfident,
    rag_context: ragContext,
    llm_provider: ($env.LLM_PROVIDER || 'openai').toLowerCase()
  }
}];

const input = $json;
const systemPrompt = `# FAQ - System Prompt

Voce responde perguntas do salao usando apenas a base de conhecimento.
Retorne JSON com answer e confidence (0 a 1).
Se nao souber, confidence deve ser menor que 0.7 e answer deve indicar que vai confirmar com a equipe.`;
const userPrompt = `Pergunta do cliente: ${input.message}

Contexto RAG:
${input.rag_context}`;
return [{ json: { ...input, system_prompt: systemPrompt, user_prompt: userPrompt } }];

const source = $items('Build FAQ Prompt', 0, 0)[0].json;
let payload = { answer: 'Boa pergunta! Vou confirmar com a equipe e ja te retorno.', confidence: 0.4 };
let text = '';
if ($json.choices?.[0]?.message?.content) text = $json.choices[0].message.content;
if (!text && Array.isArray($json.content) && $json.content[0]?.text) text = $json.content[0].text;

try {
  payload = { ...payload, ...JSON.parse(text) };
} catch (e) {}

if (!source.rag_confident && payload.confidence > 0.69) {
  payload.confidence = 0.69;
}

if (typeof payload.confidence !== 'number') payload.confidence = 0.4;
const escalated = payload.confidence < 0.7;

if (escalated) {
  payload.answer = 'Boa pergunta! Vou confirmar com a equipe e ja te retorno.';
}

const safeAnswer = (payload.answer || '').replace(/'/g, "''");
const agentLabel = escalated ? 'faq_handoff' : 'faq';
return [{
  json: {
    ...source,
    answer: safeAnswer,
    confidence: payload.confidence,
    escalated,
    agent_label: agentLabel,
    handoff_reason: escalated ? 'faq_low_confidence' : null
  }
}];
